INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('klimagesetz-oesterreich-begutachtung-endet-standortklausel-kritik','Klimagesetz Österreich: Begutachtung endet, Kritik an Standortklausel','Am 30. Oktober endet die Begutachtung des Klimagesetzes. Der Erneuerbaren-Dachverband EEÖ kritisiert fehlende Verbindlichkeit und die Standortklausel.','Das **Klimagesetz** für Österreich steht kurz vor dem nächsten Schritt: Am Freitag, 30. Oktober 2026, endet die Begutachtungsfrist für den Entwurf, den die Bundesregierung Mitte September vorgelegt hat. Kurz vor Fristende meldet sich der Dachverband Erneuerbare Energie Österreich (EEÖ) mit deutlicher Kritik zu Wort und fordert verbindliche Ziele statt bloßer Absichtserklärungen.

## Was im Entwurf zum Klimagesetz steht

Umweltminister Norbert Totschnig (ÖVP) hat den Entwurf am 18. September gemeinsam mit Vertretern von SPÖ und NEOS präsentiert. Dem Beschluss gingen laut ORF rund 13 Monate Verhandlungen voraus. Kernpunkt ist das Ziel, Österreich bis 2040 klimaneutral zu machen – zehn Jahre früher, als es die EU insgesamt anstrebt.

Der Entwurf betrifft vor allem jene Bereiche, die nicht unter den EU-Emissionshandel fallen:

- Verkehr
- Gebäude
- Kleinindustrie und Gewerbe
- Landwirtschaft
- Abfallwirtschaft

Ein erster Klimafahrplan soll bis Ende 2027 ausgearbeitet werden. Eine technische Steuerungsgruppe beobachtet die Emissionen. Drohen EU-Ziele verfehlt zu werden, muss sie innerhalb von drei Monaten eine Anpassung des Fahrplans vorschlagen, die Regierung hat danach weitere drei Monate Zeit für ein Sofortprogramm. Dazu kommen eine politische Steuerungsgruppe und ein wissenschaftlicher Klimabeirat.

## Kritik an der Standortklausel

Besonders umstritten ist die sogenannte Standortklausel. Sie erlaubt, den Klimafahrplan bei schweren wirtschaftlichen Verwerfungen anzupassen – als Beispiel nannte die Regierung eine Pandemie. Der EEÖ hält das für widersinnig: Klimamaßnahmen könnten so hintangestellt werden, sobald Wirtschaft oder Arbeitsplätze unter Druck geraten, und zwar unabhängig davon, ob die Probleme überhaupt mit Klimapolitik zu tun haben. Gleichzeitig blende der Entwurf aus, dass Investitionen in Klimaschutz die Energiesicherheit stärken.

Geschäftsführerin Martina Prechtl-Grundnig bezeichnet das Gesetz in seiner jetzigen Form sinngemäß als leeres Versprechen. Der Verband fordert:

1. ein verbindliches Klimaneutralitätsziel 2040 samt festgelegtem Reduktionspfad,
2. klar bezifferte Einsparungen für Gebäude, Verkehr und Landwirtschaft,
3. Änderungen am Ziel nur über ein strenges Verfahren im Nationalrat und nach positiver Bewertung durch den Klimabeirat.

Positiv sieht der EEÖ die vorgesehene Abstimmung zwischen Bund und Ländern, die Einbindung von Stakeholdern, den wissenschaftlichen Beirat sowie die laufende Fortschrittskontrolle mit Gegenmaßnahmen.

## Umwelttechnik als Wirtschaftsfaktor

Der Verband verweist auch auf die wirtschaftliche Bedeutung der Branche. Rund 3.326 Unternehmen der österreichischen Umwelttechnik beschäftigen etwa 57.800 Menschen. 2023 erwirtschafteten sie 21,42 Milliarden Euro Umsatz, davon 15,11 Milliarden Euro im Export. Strenge Umweltstandards würden diesen Sektor stärken, so die Argumentation.

## Emissionen über dem EU-Limit

Hintergrund der Debatte: Für 2025 wird laut ORF ein leichter Anstieg der Treibhausgasemissionen um 0,7 Prozent auf rund 67,1 Millionen Tonnen CO2-Äquivalent erwartet. Damit liegt Österreich etwa 0,8 Millionen Tonnen über dem EU-Limit für 2025. Bei der Präsentation hatte Totschnig den Zielen des Gesetzes einen deklaratorischen Charakter zugeschrieben. Kritik kam bereits im September aus unterschiedlichen Richtungen: Die FPÖ warnte vor hohen Kosten für Haushalte und Betriebe, die Grünen hielten das Bekenntnis zu 2040 für zu schwach.

## Wie es mit dem Klimagesetz weitergeht

Nach Ende der Begutachtung werden die eingelangten Stellungnahmen gesichtet. Danach muss der Entwurf noch im Ministerrat beschlossen und im Parlament behandelt werden, bevor das Klimagesetz in Kraft treten kann. Ob die Kritik an Standortklausel und fehlender Verbindlichkeit zu Änderungen führt, ist offen.','energie','Klima',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/klimagesetz-oesterreich-begutachtung-endet-standortklausel-kritik.webp','Erneuerbare Energie Österreich (EEÖ)','https://www.erneuerbare-energie.at/presseaussendungen/2026/10/29/ee-zu-klimagesetz-ambitionierte-umweltstandards-strken-sterreichs-wirtschaft','published','2026-10-29T11:50:00.000Z','2026-10-29T11:47:43.560Z','Klimagesetz Österreich: Kritik vor Begutachtungsende','Klimagesetz Österreich: Am 30. Oktober endet die Begutachtung. Erneuerbare-Verband fordert verbindliche Ziele bis 2040 – alle Details im Überblick.','Klimagesetz','["Klimagesetz","Klimagesetz Österreich","Klimaneutralität 2040","Standortklausel","Begutachtung Klimagesetz","Klimafahrplan 2027","Erneuerbare Energie Österreich","Totschnig Klimagesetz","Klimabeirat"]','Klimagesetz Österreich: Alpental mit Windrad, Solardächern und Bahn im Herbst','Austrian alpine valley in late autumn with a small town, a wind turbine on a ridge, solar panels on farmhouse roofs and a regional train crossing the valley, no text, no logos, no readable signs','[{"q":"Wann endet die Begutachtung des Klimagesetzes?","a":"Die Begutachtungsfrist für den Entwurf endet am Freitag, 30. Oktober 2026."},{"q":"Welches Ziel verfolgt das Klimagesetz?","a":"Österreich soll bis 2040 klimaneutral werden. Ein erster Klimafahrplan ist bis Ende 2027 vorgesehen."},{"q":"Was ist die Standortklausel?","a":"Sie erlaubt, den Klimafahrplan bei schweren wirtschaftlichen Verwerfungen anzupassen. Kritiker sehen darin ein Schlupfloch."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=e